				Database: config.DatabaseConfig{
					URL: "http://a b",
				},
			},
			wantErr: true,
		},
		{
			name: "unknown driver",
			cfg: config.Config{
				Database: config.DatabaseConfig{
					URL: "mongo://127.0.0.1",
				},
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		var (
			cfg     = tt.cfg
			driver  = tt.driver
			wantErr = tt.wantErr
